<script setup lang="ts">
import { computed, reactive, ref } from 'vue'; import { Head, router, usePage } from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue';
const page = usePage<any>(); const form = reactive({ ingredient_id: '', qty_per_unit: 1 }); const processing = ref(false); const canEdit = computed(() => Boolean(page.props.auth?.permissions?.MenuItemResource?.can_edit));
function save() { if (processing.value) return; processing.value = true; router.post(`/app/master/menus/${page.props.menu.id}/recipes`, form, { onSuccess: () => { form.ingredient_id = ''; form.qty_per_unit = 1; }, onFinish: () => { processing.value = false; } }); }
function remove(id: number) { if (processing.value || !confirm('Hapus bahan dari resep ini?')) return; processing.value = true; router.delete(`/app/master/menus/${page.props.menu.id}/recipes/${id}`, { onFinish: () => { processing.value = false; } }); }
</script>
<template><Head title="Resep Menu"/><AppLayout><template #title>Resep Menu</template><div class="mx-auto max-w-3xl space-y-6"><div><p class="text-xs font-bold uppercase tracking-[0.22em] text-lime-700">Produk</p><h2 class="mt-1 text-2xl font-semibold">Resep {{ page.props.menu.name }}</h2></div><form v-if="canEdit" class="flex flex-col gap-3 rounded-3xl border border-stone-200 bg-white p-6 shadow-sm sm:flex-row sm:items-end" @submit.prevent="save"><label class="field flex-1">Bahan<select v-model="form.ingredient_id" required><option value="">Pilih bahan</option><option v-for="item in page.props.ingredients" :key="item.id" :value="item.id">{{ item.name }} ({{ item.unit }})</option></select></label><label class="field">Qty per unit<input v-model.number="form.qty_per_unit" type="number" min="0.001" step="0.001" required></label><button :disabled="processing" class="rounded-xl bg-stone-900 px-4 py-3 text-sm font-semibold text-white disabled:opacity-50">{{ processing ? 'Menyimpan...' : 'Simpan' }}</button></form><section class="overflow-hidden rounded-3xl border border-stone-200 bg-white shadow-sm"><div v-for="recipe in page.props.recipes" :key="recipe.id" class="flex items-center justify-between border-b border-stone-100 px-5 py-4 last:border-0"><div><p class="font-medium">{{ recipe.ingredient_name }}</p><p class="text-sm text-stone-500">{{ recipe.qty_per_unit }} {{ recipe.unit }} per menu</p></div><button v-if="canEdit" :disabled="processing" class="text-sm text-red-600 disabled:opacity-40" @click="remove(recipe.id)">Hapus</button></div><p v-if="!page.props.recipes.length" class="p-10 text-center text-stone-500">Belum ada resep.</p></section></div></AppLayout></template>
<style scoped>.field{display:block;color:#57534e;font-size:.8rem}.field input,.field select{display:block;width:100%;margin-top:.35rem;border:1px solid #e7e5e4;border-radius:.8rem;background:#fafaf9;padding:.7rem .8rem;font-size:.875rem;color:#1c1917}</style>
